/**
 * Kysely's view of the schema.
 *
 * TIER 0 — deliberately EMPTY. There are no tables yet: Tier 0 creates zero
 * migrations (ADU-CON-02 v3.0 section 15).
 *
 * This interface is NOT hand-maintained. From Tier 1 it is generated by
 * `kysely-codegen` from the live database, which is the whole reason there is no
 * ORM (section 3.4): types are derived from the migrations, so they cannot drift
 * from them, and an agent that invents a column writes code that does not
 * compile. Hand-adding a table here would defeat exactly that property.
 */
// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface Database {}
